# ---------------------------------------------------------------------------
# Shared reduction primitive.
#
# PyTorch scans a pooling window in (kd, kh, kw) order and keeps an element
# when it is strictly greater than the current best, or when it is NaN (a NaN
# therefore always propagates and the *last* NaN of the window wins, while
# ordinary ties keep the first occurrence).  The tuple combine below implements
# exactly that rule, so a tree reduction over one axis yields the same
# (value, position) pair as the sequential scan as long as the tree preserves
# the scan order along that axis.
# ---------------------------------------------------------------------------
@triton.jit
def _combine_max_idx(a_val, a_idx, b_val, b_idx):
    take_b = (b_val > a_val) | (b_val != b_val)
    return tl.where(take_b, b_val, a_val), tl.where(take_b, b_idx, a_idx)


# ---------------------------------------------------------------------------
# Integer-ratio fast path.
#
# When alpha == kernel_size on every spatial axis the pooling windows tile the
# input exactly: start(i) == i * alpha (also for the last position, because
# alpha * (out - 1) == in - kernel), so the input block belonging to a tile of
# output elements is a plain strided block.  Every input element is therefore
# read exactly once with wide contiguous loads, and the (kernel_d, kernel_h,
# kernel_w) window is folded inside the block.
# ---------------------------------------------------------------------------
@libentry()
@triton.jit
def _fractional_max_pool3d_ratio_kernel(
    in_ptr,
    out_ptr,
    idx_ptr,
    s_n,
    s_c,
    s_d,
    s_h,
    s_w,
    in_c,
    in_h,
    in_w,
    out_d,
    out_h,
    out_w,
    AD: tl.constexpr,
    AH: tl.constexpr,
    AW: tl.constexpr,
    BLOCK_H: tl.constexpr,
    BLOCK_W: tl.constexpr,
    WRITE_IDX: tl.constexpr,
):
    pid_ncod = tl.program_id(0)
    pid_h = tl.program_id(1)
    pid_w = tl.program_id(2)

    od = pid_ncod % out_d
    nc = pid_ncod // out_d
    n_idx = nc // in_c
    c_idx = nc % in_c

    oh0 = pid_h * BLOCK_H
    ow0 = pid_w * BLOCK_W
    oh = oh0 + tl.arange(0, BLOCK_H)
    ow = ow0 + tl.arange(0, BLOCK_W)

    # Row/column lanes of the input block. AH/AW are the window extents as well
    # as the strides of the pooling grid; the padded lanes of a non power of two
    # window are masked out of the reduction below.
    row_lane = tl.arange(0, BLOCK_H * AH)
    col_lane = tl.arange(0, BLOCK_W * AW)
    row_kh = row_lane % AH
    col_kw = col_lane % AW
    row_in = tl.minimum(oh0 * AH + (row_lane // AH) * AH + row_kh, in_h - 1)
    col_in = tl.minimum(ow0 * AW + (col_lane // AW) * AW + col_kw, in_w - 1)

    base = in_ptr + n_idx * s_n + c_idx * s_c + (od * AD) * s_d
    off2d = row_in[:, None] * s_h + col_in[None, :] * s_w

    kv = tl.broadcast_to(
        tl.arange(0, AW)[None, None, None, :], (BLOCK_H, AH, BLOCK_W, AW)
    ).to(tl.int32)
    khv = tl.broadcast_to(tl.arange(0, AH)[None, :, None], (BLOCK_H, AH, BLOCK_W)).to(
        tl.int32
    )

    best_v = tl.zeros((BLOCK_H, BLOCK_W), dtype=in_ptr.type.element_ty)
    best_i = tl.zeros((BLOCK_H, BLOCK_W), dtype=tl.int32)

    for kd in tl.static_range(AD):
        x = tl.load(base + kd * s_d + off2d)
        x4 = tl.reshape(x, (BLOCK_H, AH, BLOCK_W, AW))
        v1, k1 = tl.reduce((x4, kv), 3, _combine_max_idx)
        v2, k2 = tl.reduce((v1, khv * AW + k1), 1, _combine_max_idx)
        h_in = oh[:, None] * AH + (k2 // AW)
        w_in = ow[None, :] * AW + (k2 % AW)
        flat = ((od * AD + kd) * in_h + h_in) * in_w + w_in
        if kd == 0:
            best_v = v2
            best_i = flat
        else:
            best_v, best_i = _combine_max_idx(best_v, best_i, v2, flat)

    out_off = ((nc * out_d + od) * out_h + oh[:, None]) * out_w + ow[None, :]
    store_mask = (oh[:, None] < out_h) & (ow[None, :] < out_w)
    tl.store(out_ptr + out_off, best_v, mask=store_mask)
    if WRITE_IDX:
        tl.store(idx_ptr + out_off, best_i.to(tl.int64), mask=store_mask)


