    # also covers a length one output axis, where alpha is zero.
    h_start = tl.where(ho == out_h - 1, in_h - KH, h_start)
    w_start = tl.where(wo == out_w - 1, in_w - KW, w_start)

    d_start = ((d_idx.to(tl.float32) + sample_d) * alpha_d).to(tl.int32) - sample_alpha_d
    d_start = tl.where(d_idx == out_d - 1, in_d - KD, d_start)

    h_base = h_start[:, None]
    w_base = w_start[None, :]

